package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	total := 0
	for i := 0; i < n; i++ {
		var name string
		var qty, price int
		if _, err := fmt.Fscan(in, &name, &qty, &price); err != nil {
			break
		}
		total += qty * price
	}
	fmt.Println(total)
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long total = 0;
        for (int i = 0; i < n; i++) {
            in.next();
            long qty = in.nextLong();
            long price = in.nextLong();
            total += qty * price;
        }
        System.out.println(total);
    }
}

