const lines = require('fs').readFileSync(0, 'utf8').split('\n');
const count = new Map();
const first = new Map();
lines.forEach((raw, i) => {
  const name = raw.trim();
  if (!name) return;
  count.set(name, (count.get(name) || 0) + 1);
  if (!first.has(name)) first.set(name, i);
});
let best = null;
for (const [name, n] of count) {
  if (best === null || n > count.get(best) || (n === count.get(best) && first.get(name) < first.get(best))) best = name;
}
console.log(best);

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	count := map[string]int{}
	first := map[string]int{}
	i := 0
	for sc.Scan() {
		name := strings.TrimSpace(sc.Text())
		i++
		if name == "" {
			continue
		}
		count[name]++
		if _, ok := first[name]; !ok {
			first[name] = i
		}
	}
	best := ""
	for name, n := range count {
		if best == "" || n > count[best] || (n == count[best] && first[name] < first[best]) {
			best = name
		}
	}
	fmt.Println(best)
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        Map<String, Integer> count = new LinkedHashMap<>();
        String line;
        while ((line = in.readLine()) != null) {
            String name = line.trim();
            if (name.isEmpty()) continue;
            count.merge(name, 1, Integer::sum);
        }
        String best = null;
        for (Map.Entry<String, Integer> e : count.entrySet()) {
            if (best == null || e.getValue() > count.get(best)) best = e.getKey();
        }
        System.out.println(best);
    }
}
